Only the first 16 output classes have large weights, so the rules use classes 0-15; I print each skill's predicted table to read the rules from the network.

```python
import numpy as np
def silu(x): return x/(1+np.exp(-x))
def fwd(P,skill):
    a=np.repeat(np.arange(32),32); b=np.tile(np.arange(32),32)
    X=np.zeros((1024,68)); X[np.arange(1024),a]=1; X[np.arange(1024),32+b]=1; X[:,64+skill]=1
    h=silu(X@P["l1.weight"].T+P["l1.bias"]); h=silu(h@P["l2.weight"].T+P["l2.bias"]); return h@P["l3.weight"].T+P["l3.bias"]
P={n:load(n) for n in NAMES}
np.set_printoptions(linewidth=250)
for s in range(4):
    L=fwd(P,s); p=L.argmax(1).reshape(32,32)
    e=np.exp(L-L.max(1,keepdims=True)); conf=(1/e.sum(1)).reshape(32,32)
    print("skill",s,"class counts",np.bincount(p.ravel(),minlength=63)[:20],"mean conf",round(conf.mean(),3),"frac conf<.7",round((conf<.7).mean(),3))
    for row in p[:16]: print(" ".join("%2d"%v for v in row))
