The tables look structured: skill 3 looks additive in hidden per-number values, skill 2 like a product mod 16, skill 1 like a max or a condition, and skill 0 is unclear. I test those rule hypotheses against the network's own predictions, with no weight changes.

```python
import numpy as np, pickle
def silu(x): return x/(1+np.exp(-x))
def fwd(P,skill):
    a=np.repeat(np.arange(32),32); b=np.tile(np.arange(32),32)
    X=np.zeros((1024,68)); X[np.arange(1024),a]=1; X[np.arange(1024),32+b]=1; X[:,64+skill]=1
    h=silu(X@P["l1.weight"].T+P["l1.bias"]); h=silu(h@P["l2.weight"].T+P["l2.bias"]); return h@P["l3.weight"].T+P["l3.bias"]
P={n:load(n) for n in NAMES}
T={};C={}
for s in range(4):
    L=fwd(P,s); T[s]=L.argmax(1).reshape(32,32)
    e=np.exp(L-L.max(1,keepdims=True)); C[s]=(1/e.sum(1)).reshape(32,32)
pickle.dump((T,C),open("tab.pkl","wb"))
np.set_printoptions(linewidth=250)
def fit(op,K,s,M,restarts=30,seed=0):
    rng=np.random.default_rng(seed); t=T[s]; w=C[s]; best=None
    tab=np.array([[op(i,j) for j in range(K)] for i in range(K)])
    for r in range(restarts):
        u=rng.integers(0,K,32); v=rng.integers(0,K,32)
        for it in range(12):
            for a in range(32):
                u[a]=np.argmax([(w[a]*(tab[i,v]==t[a])).sum() for i in range(K)])
            for b in range(32):
                v[b]=np.argmax([(w[:,b]*(tab[u,j]==t[:,b])).sum() for j in range(K)])
        ag=(tab[u][:,v]==t).mean()
        if best is None or ag>best[0]: best=(ag,u.copy(),v.copy())
    return best
ops={"add":lambda i,j:i+j,"mul16":lambda i,j:(i*j)%16,"add16":lambda i,j:(i+j)%16,"xor":lambda i,j:i^j,"max":lambda i,j:max(i,j),"min":lambda i,j:min(i,j),"and":lambda i,j:i&j,"or":lambda i,j:i|j}
for s,names,K in [(3,["add"],8),(3,["add16","xor"],16),(2,["mul16","add16","xor"],16),(1,["max","min","or","and","xor"],8)]:
    for nm in names:
        b=fit(ops[nm],K,s,None,restarts=6)
        print("skill",s,nm,"K",K,"agree",round(b[0],3)); print(" u",b[1]); print(" v",b[2])
